package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import jakarta.servlet.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.ObjectProvider;
/** Authenticated deployment discovery, including when the author is disabled. No grants are inferred. */
@RestController public final class ModelRuntimeAvailabilityController {
 private final ApplicationSessionIdentity identities;private final EnterpriseAccess access;private final ObjectProvider<ModelRuntimeController> controllers;private final PermissionSchema json;
 public ModelRuntimeAvailabilityController(ApplicationSessionIdentity identities,EnterpriseAccess access,ObjectProvider<ModelRuntimeController> controllers,PermissionSchema json){this.identities=identities;this.access=access;this.controllers=controllers;this.json=json;}
 @GetMapping("/api/model-runtime-availability") public JsonNode read(HttpServletRequest request,HttpServletResponse response,Authentication authentication){if(request.getQueryString()!=null||request.getContentLengthLong()>0||request.getHeader("Transfer-Encoding")!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);if(!"1.0.0".equals(SimulationInputArtifactController.one(request,"X-Schema-Version")))throw new SchemaRejection(ErrorCode.SCHEMA_UNSUPPORTED);String context=SimulationInputArtifactController.one(request,"X-Context-Revision");PermissionSchema.revision(context);var data=access.execute(identities.requireCurrent(request,authentication),a->{if(!context.equals(a.context().context_revision()))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);var d=json.object().put("schema_version","1.0.0").put("model_runtime_enabled",controllers.getIfAvailable()!=null);d.put("supported_model_scope","PROJECT");d.set("supported_providers",json.tree(java.util.List.of("DEEPSEEK")));d.set("supported_reasoning_efforts",json.tree(java.util.List.of("none")));d.set("current_context",json.tree(a.context()));return d;});String id=java.util.UUID.randomUUID().toString();response.setHeader("Cache-Control","no-store");response.setHeader("X-Schema-Version","1.0.0");response.setHeader("X-Resource-Revision",context);response.setHeader("X-Request-Id",id);return json.tree(new InterfaceProtocol.Envelope("1.0.0",id,context,data));}
 @ExceptionHandler(SchemaRejection.class) void invalid(SchemaRejection failure,HttpServletResponse response)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(response,422,failure.code());}
 @ExceptionHandler(TenantAccessException.class) void denied(TenantAccessException failure,HttpServletResponse response)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(response,SimulationRuleVersionController.errorStatus(failure.code()),failure.code());}
}
